const store = useWorkbenchStore(); const ui=useUiStore(); const imageFiles=ref<File[]>([]); const images = ref<{ name: string; url: string }[]>([]); const layout = ref<'single' | 'pair' | 'grid'>('single'); const title = ref(''); const watermark = ref('ToolKnit'); const background = ref('#172321'); const exporting = ref(false); const message = ref('导入图片，选择布局后生成一张可分享的 PNG。')
