const annotationTool = ref<AnnotationKind>('box'); const annotationText = ref('重点'); const annotationColor = ref('#ffbf69'); const annotations = ref<Annotation[]>([])
const slots = computed(() => layout.value === 'single' ? 1 : layout.value === 'pair' ? 2 : 4)
watch(imageFiles, selected=>{images.value.forEach(item=>URL.revokeObjectURL(item.url));images.value=selected.slice(0,4).map(file=>({name:file.name,url:URL.createObjectURL(file)}));message.value=images.value.length?`已载入 ${images.value.length} 张图片。`:'请选择图片文件。'})
function placeAnnotation(event: MouseEvent) { if (!images.value.length) return; const target = event.currentTarget as HTMLElement; const rect = target.getBoundingClientRect(); const x = Math.max(.03, Math.min(.92, (event.clientX - rect.left) / rect.width)); const y = Math.max(.06, Math.min(.91, (event.clientY - rect.top) / rect.height)); annotations.value.push({ id: Date.now() + Math.random(), kind: annotationTool.value, x, y, text: annotationText.value.trim() || '重点', color: annotationColor.value }); message.value = '标注已添加到导出预览。' }
