function drawCover(ctx: CanvasRenderingContext2D, image: HTMLImageElement, x: number, y: number, width: number, height: number) { const ratio = Math.max(width / image.naturalWidth, height / image.naturalHeight); const drawWidth = image.naturalWidth * ratio; const drawHeight = image.naturalHeight * ratio; ctx.drawImage(image, x + (width - drawWidth) / 2, y + (height - drawHeight) / 2, drawWidth, drawHeight) }
async function exportCard() { if (!images.value.length) { message.value = '先至少导入一张图片。'; return } if(isDesktop()&&!store.settings.outputDirectory){const directory=await chooseOutputDirectory();if(!directory)return;store.updateSettings({outputDirectory:directory})} exporting.value = true; try { const canvas = document.createElement('canvas'); canvas.width = 1600; canvas.height = layout.value === 'single' ? 1100 : 1200; const ctx = canvas.getContext('2d'); if (!ctx) throw new Error('浏览器不支持画布导出。'); ctx.fillStyle = background.value; ctx.fillRect(0, 0, canvas.width, canvas.height); const loaded = await Promise.all(images.value.map((item) => new Promise<HTMLImageElement>((resolve, reject) => { const image = new Image(); image.onload = () => resolve(image); image.onerror = reject; image.src = item.url }))); const pad = 48; const titleHeight = title.value.trim() ? 130 : 50; const areaY = titleHeight; const areaH = canvas.height - titleHeight - 48; if (layout.value === 'single') drawCover(ctx, loaded[0], pad, areaY, canvas.width - pad * 2, areaH); else if (layout.value === 'pair') { const width = (canvas.width - pad * 3) / 2; [0, 1].forEach((index) => loaded[index] && drawCover(ctx, loaded[index], pad + index * (width + pad), areaY, width, areaH)) } else { const width = (canvas.width - pad * 3) / 2, height = (areaH - pad) / 2; [0, 1, 2, 3].forEach((index) => loaded[index] && drawCover(ctx, loaded[index], pad + (index % 2) * (width + pad), areaY + Math.floor(index / 2) * (height + pad), width, height)) } if (title.value.trim()) { ctx.fillStyle = '#f2f6f2'; ctx.font = '600 46px "Noto Sans SC", sans-serif'; ctx.fillText(title.value.trim().slice(0, 42), pad, 73) } annotations.value.forEach((annotation) => drawAnnotation(ctx, annotation, canvas.height)); ctx.fillStyle = '#a7cdb9'; ctx.font = '500 20px ui-monospace, monospace'; ctx.textAlign = 'right'; ctx.fillText(watermark.value || 'ToolKnit', canvas.width - pad, canvas.height - 19); const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('无法生成 PNG。');const name=`toolknit-card-${Date.now()}.png`;const output=await exportOutput(store.settings.outputDirectory,name,blob,'image/png'); const job = store.addJob('image', '图片分享卡', images.value.map((item) => item.name),{toolId:'visual-card',route:'/visual',inputs:imageFiles.value.map(f=>({name:f.name,size:f.size,mime:f.type,path:(f as File&{path?:string}).path})),parameters:{layout:layout.value,title:title.value,watermark:watermark.value,background:background.value},retryable:true}); store.updateJob(job.id, { status: 'succeeded', progress: 100, outputNames: [name], outputs:[output], detail: '已导出新的 PNG 分享卡。' }); message.value = 'PNG 分享卡已导出。';ui.toast('图片分享卡已生成',output.path||name,'success') } catch (error) { message.value = error instanceof Error ? error.message : '导出失败。';ui.toast('导出失败',message.value,'error') } finally { exporting.value = false } }
