<template>
  <div class="visual-studio page-enter"><section class="page-heading"><div><p class="eyebrow">IMAGE EXPRESSION STUDIO</p><h2>把几张图片，<em>组织成一句完整表达。</em></h2><p>本工具只使用你主动导入的图片，在本地画布中合成并导出新的 PNG。</p></div></section><section class="visual-grid"><aside class="visual-controls"><p class="eyebrow">01 · CONTENT</p><FileDropZone v-model="imageFiles" accept="image/*" title="拖入图片" hint="最多使用前 4 张图片" @error="message=$event"/><p class="eyebrow">02 · LAYOUT</p><div class="layout-options"><button :class="{ active: layout === 'single' }" @click="layout = 'single'">单图</button><button :class="{ active: layout === 'pair' }" @click="layout = 'pair'">双图</button><button :class="{ active: layout === 'grid' }" @click="layout = 'grid'">四宫格</button></div><label>标题<input v-model="title" placeholder="可选，例如：本周记录" /></label><label>水印<input v-model="watermark" /></label><label>背景色<input v-model="background" type="color" /></label><div class="annotation-controls"><p class="eyebrow">03 · ANNOTATE</p><div class="layout-options"><button :class="{ active: annotationTool === 'box' }" @click="annotationTool = 'box'">方框</button><button :class="{ active: annotationTool === 'arrow' }" @click="annotationTool = 'arrow'">箭头</button><button :class="{ active: annotationTool === 'text' }" @click="annotationTool = 'text'">文字</button></div><label>标注文字<input v-model="annotationText" /></label><label>标注颜色<input v-model="annotationColor" type="color" /></label><p class="annotation-hint">选择样式后，直接点右侧预览放置标注。</p></div></aside><main class="visual-preview"><header><p class="eyebrow">03 · EXPORT PREVIEW</p><span>{{ images.length }}/{{ slots }} 图片</span></header><div class="card-preview annotation-canvas" :style="{ background }" @click="placeAnnotation"><h3 v-if="title">{{ title }}</h3><div class="preview-images" :class="layout"><img v-for="item in images.slice(0, slots)" :key="item.url" :src="item.url" :alt="item.name" /><span v-if="!images.length">预览区域</span></div><button v-for="annotation in annotations" :key="annotation.id" class="annotation-mark" :class="annotation.kind" :style="{ left: `${annotation.x * 100}%`, top: `${annotation.y * 100}%`, color: annotation.color, borderColor: annotation.color }" title="点击删除标注" @click.stop="removeAnnotation(annotation.id)">{{ annotation.kind === 'arrow' ? '↗' : annotation.kind === 'text' ? annotation.text : '' }}</button><small>{{ watermark || 'ToolKnit' }}</small></div><footer><p>{{ message }}</p><button class="run-tool" :disabled="exporting" @click="exportCard">{{ exporting ? '正在导出…' : '导出 PNG 分享卡' }}</button></footer></main></section></div>
